    dt = ndimage.distance_transform_edt(h)
    mx = ndimage.maximum_filter(dt, size=5)
    peaks = (dt == mx) & (dt >= 2.3)
    py, px = np.where(peaks)
    for a, b in zip(px, py):
        cands.append((float(a), float(b)))

# 2. local color vote in radius-4 window
def vote(cx, cy, rad=4):
    x0, x1 = int(max(0,round(cx)-rad)), int(min(A.shape[1],round(cx)+rad+1))
    y0, y1 = int(max(0,round(cy)-rad)), int(min(A.shape[0],round(cy)+rad+1))
    sub = np.zeros_like(holes)
    yy, xx = np.ogrid[0:A.shape[0], 0:A.shape[1]]
    d2 = (xx-cx)**2 + (yy-cy)**2
    win = d2 <= (rad+0.5)**2
    counts = {k: int((win & masks[k]).sum()) for k in HUE}
